const now = new Date();
const vnNow = new Date(now.toLocaleString('en-US', { timeZone: 'Asia/Ho_Chi_Minh' }));
const yesterday = new Date(vnNow);
yesterday.setDate(vnNow.getDate() - 1);

const pad = (n) => String(n).padStart(2, '0');
const fmtISO = (d) => `${d.getFullYear()}-${pad(d.getMonth()+1)}-${pad(d.getDate())}`;
const fmtVN = (d) => `${pad(d.getDate())}/${pad(d.getMonth()+1)}/${d.getFullYear()}`;

return [{
  json: {
    yesterdayISO: fmtISO(yesterday),
    todayISO: fmtISO(vnNow),
    yesterdayVN: fmtVN(yesterday),
    todayVN: fmtVN(vnNow),
    yesterdayStart: `${fmtISO(yesterday)}T00:00:00.000+07:00`,
    todayStart: `${fmtISO(vnNow)}T00:00:00.000+07:00`
  }
}];

const dateInfo = $('Compute Dates').first().json;
const yesterdayVN = dateInfo.yesterdayVN;
const todayVN = dateInfo.todayVN;

const salesResults = $('Query Sales (Notion)').first().json.results || [];
const leadsResults = $('Query Leads (Notion)').first().json.results || [];
const cashResults = $('Query Cash (Notion)').first().json.results || [];
const revenueResults = $('Query Revenue (Notion)').first().json.results || [];
const expenseResults = $('Query Expenses (Notion)').first().json.results || [];

const fmtVND = (n) => Math.round(n).toLocaleString('vi-VN') + ' đ';
const esc = (s) => String(s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');

// ===== 1. Sales Tracker (per-deal, sales tự nhập) =====
let stDoanhThu = 0, stDaThu = 0;
const salePerf = {};
for (const s of salesResults) {
  const p = s.properties || {};
  const giatri = p['Giá trị (VNĐ)']?.number || 0;
  const dathu = p['Đã thu (VNĐ)']?.number || 0;
  stDoanhThu += giatri; stDaThu += dathu;
  const sale = p['Sale']?.select?.name;
  if (sale) salePerf[sale] = (salePerf[sale] || 0) + giatri;
}

// ===== 2. Revenue Daily (từ Excel — tiền thực vào) =====
let revTong = 0;
const revByLoai = {};
for (const r of revenueResults) {
  const p = r.properties || {};
  const amt = p['Số tiền vào (VNĐ)']?.number || 0;
  revTong += amt;
  const loai = p['Loại']?.select?.name || 'Khác';
  revByLoai[loai] = (revByLoai[loai] || 0) + amt;
}

// ===== 3. Cash Position (1 record/ngày) =====
let cashVao = 0, cashRa = 0, tkPK = 0, tkCTY = 0;
if (cashResults.length > 0) {
  const p = cashResults[0].properties || {};
  cashVao = p['Tổng tiền vào (VNĐ)']?.number || 0;
  cashRa = p['Tổng tiền ra (VNĐ)']?.number || 0;
  tkPK = p['TK Phòng Khám cuối (VNĐ)']?.number || 0;
  tkCTY = p['TK CTY cuối (VNĐ)']?.number || 0;
}

// ===== 4. Expenses (chi tiết) =====
let chiTong = 0;
const chiByCat = {};
for (const e of expenseResults) {
  const p = e.properties || {};
  const amt = p['Số tiền ra (VNĐ)']?.number || 0;
  chiTong += amt;
  const cat = p['Hạng mục']?.select?.name || 'Khác';
  chiByCat[cat] = (chiByCat[cat] || 0) + amt;
}

// ===== Build message =====
let msg = `<b>📊 DRSKIN DASHBOARD — ${todayVN}</b>\n`;
msg += `<i>Báo cáo ngày ${yesterdayVN}</i>\n\n`;

// Dòng tiền tổng quan
msg += `<b>📊 DÒNG TIỀN (Excel)</b>\n`;
if (cashResults.length > 0) {
  msg += `• Tiền vào: <b>${fmtVND(cashVao)}</b>\n`;
  msg += `• Tiền ra: <b>${fmtVND(cashRa)}</b>\n`;
  msg += `• TK Phòng Khám cuối: ${fmtVND(tkPK)}\n`;
  msg += `• Két riêng (CTY) cuối: ${fmtVND(tkCTY)}\n\n`;
} else {
  msg += `• ⚠️ Chưa có data Excel ngày này\n\n`;
}

// Doanh thu từ Excel (theo loại)
msg += `<b>📚 DOANH THU GHI NHẬN (Excel)</b>\n`;
if (revTong > 0) {
  for (const [loai, amt] of Object.entries(revByLoai).sort((a,b)=>b[1]-a[1])) {
    if (amt > 0) msg += `  • ${esc(loai)}: ${fmtVND(amt)}\n`;
  }
  msg += `  • <b>Tổng: ${fmtVND(revTong)}</b>\n\n`;
} else {
  msg += `  • Không có doanh thu ghi nhận\n\n`;
}

// Chi tiêu
msg += `<b>💸 CHI TIÊU (Excel)</b>\n`;
if (chiTong > 0) {
  const topCats = Object.entries(chiByCat).sort((a,b)=>b[1]-a[1]).slice(0, 5);
  for (const [cat, amt] of topCats) {
    msg += `  • ${esc(cat)}: ${fmtVND(amt)}\n`;
  }
  msg += `  • <b>Tổng chi: ${fmtVND(chiTong)}</b> (${expenseResults.length} khoản)\n\n`;
} else {
  msg += `  • Không có chi tiêu\n\n`;
}

// Sales Tracker (deal sales nhập tay)
msg += `<b>💰 SALES TRACKER (deal)</b>\n`;
msg += `• Ký hợp đồng: <b>${fmtVND(stDoanhThu)}</b>\n`;
msg += `• Đã thu: <b>${fmtVND(stDaThu)}</b>\n`;
msg += `• Số deal: <b>${salesResults.length}</b>\n`;
const saleEntries = Object.entries(salePerf).filter(([,a]) => a > 0).sort((a,b)=>b[1]-a[1]);
for (const [s, amt] of saleEntries) {
  msg += `  • ${esc(s)}: ${fmtVND(amt)}\n`;
}
msg += `\n`;

// ===== ĐỐI SOÁT: Sales Tracker vs Revenue Excel =====
msg += `<b>⚖️ ĐỐI SOÁT</b>\n`;
const chenh = stDoanhThu - revTong;
const absChenh = Math.abs(chenh);
if (revTong === 0 && stDoanhThu === 0) {
  msg += `• Không có giao dịch để đối soát\n`;
} else if (absChenh <= 1000) {
  msg += `• ✅ Khớp: Sales Tracker = Excel (${fmtVND(revTong)})\n`;
} else {
  msg += `• ⚠️ LỆCH ${fmtVND(absChenh)}\n`;
  msg += `  - Sales Tracker (deal ký): ${fmtVND(stDoanhThu)}\n`;
  msg += `  - Excel (tiền ghi nhận): ${fmtVND(revTong)}\n`;
  msg += `  → Kiểm tra: sales nhập thiếu deal hoặc tiền chưa về TK\n`;
}
msg += `\n`;

// Leads
const leadSources = {};
for (const l of leadsResults) {
  const src = l.properties?.['Nguồn']?.select?.name || 'Chưa rõ';
  leadSources[src] = (leadSources[src] || 0) + 1;
}
msg += `<b>🎯 LEADS MỚI</b>\n`;
msg += `• Tổng: <b>${leadsResults.length}</b> lead\n`;
for (const [src, n] of Object.entries(leadSources).sort((a,b)=>b[1]-a[1])) {
  msg += `  • ${esc(src)}: ${n}\n`;
}

const genTime = new Date().toLocaleString('vi-VN', {timeZone:'Asia/Ho_Chi_Minh'});
msg += `\n🤖 <i>n8n auto • ${genTime}</i>`;

return [{
  json: {
    message: msg,
    salesCount: salesResults.length,
    revenueTotal: revTong,
    cashVao: cashVao,
    chiTong: chiTong,
    leadsCount: leadsResults.length,
    chenhDoiSoat: chenh
  }
}];
